<script setup lang="ts">
import { Save, SlidersHorizontal } from 'lucide-vue-next'
const { api } = useApi(); const { show } = useToast(); const { data: pricing, refresh } = await useAsyncData('admin-pricing', () => api<any>('/v1/platform-admin/pricing'))
async function save(item: any) { await api(`/v1/platform-admin/pricing/${item.feature_key}`, { method: 'PATCH', body: { provider: item.provider, integration: item.integration, model_id: item.model_id, provider_cost_per_unit_usd: Number(item.provider_cost_per_unit_usd), charge_cents: Math.round(Number(item.charge_usd) * 100), margin_percent: Number(item.margin_percent), is_active: item.is_active } }); await refresh(); show('Price saved', item.label, 'success') }
watchEffect(() => { for (const item of pricing.value?.items || []) if (item.charge_usd == null) item.charge_usd = Number(item.charge_cents || 0) / 100 })
</script>
<template><div><UiPageHeader eyebrow="Unit economics" title="Models & pricing" description="Provider cost, customer dollar charge and margin for every billable integration." /><UiAppCard><div class="section-heading"><div><h2>Editable price rules</h2><p>Video rules are per generated second; customer defaults include a 20% markup.</p></div><SlidersHorizontal :size="18" /></div><div class="pricing-list"><article v-for="item in pricing?.items || []" :key="item.feature_key"><header><div><strong>{{ item.label }}</strong><small>{{ item.feature_key }} · {{ item.unit }}</small></div><label><input v-model="item.is_active" type="checkbox"> Active</label></header><div class="fields"><label>Provider<input v-model="item.provider"></label><label>Integration<input v-model="item.integration"></label><label>Model<input v-model="item.model_id"></label><label>Provider cost / unit, USD<input v-model.number="item.provider_cost_per_unit_usd" type="number" min="0" step="0.0001"></label><label>Customer charge / unit, USD<input v-model.number="item.charge_usd" type="number" min="0" step="0.01"></label><label>Margin, %<input v-model.number="item.margin_percent" type="number" step="0.1"></label></div><button class="button button--small" @click="save(item)"><Save :size="14" /> Save</button></article></div></UiAppCard></div></template>
<style scoped>.pricing-list{display:grid;gap:12px}.pricing-list article{border:1px solid var(--border);border-radius:12px;padding:13px}.pricing-list header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.pricing-list header div{display:grid;gap:2px}.pricing-list strong{font-size:11px}.pricing-list small{font-size:8px;color:var(--muted)}.pricing-list header label{display:flex;gap:5px;font-size:8px}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:9px}.fields label{display:grid;gap:4px;font-size:8px;font-weight:800}.fields input{border:1px solid var(--border);border-radius:8px;padding:8px;font-size:9px}@media(max-width:800px){.fields{grid-template-columns:1fr}}</style>
